/**
 * Map from revisionId to clientId
 */
const CHAT_MESSAGE_MAP = new Map<string, string>()
/**
 * Map from command to clientId
 */
const COMMAND_MAP = new Map<string, string>()

export const setRevisionIdForClientId = ({
	clientId,
	revisionId
}: {
	clientId: string
	revisionId: string
}) => {
	CHAT_MESSAGE_MAP.set(revisionId, clientId)
}

export const setCommandForClientId = ({
	clientId,
	command
}: {
	clientId: string
	command: string
}) => {
	COMMAND_MAP.set(command, clientId)
}

export const getClientIdForMessageId = (messageId: string) => {
	return (
		CHAT_MESSAGE_MAP.get(messageId) ?? COMMAND_MAP.get(messageId) ?? messageId
	)
}

export const getIdForCommand = (command: string) => {
	return COMMAND_MAP.get(command) ?? command
}
